put_search_settings.code:
import (
	"fmt"
)

resp, err := client.SearchSettings().PutSearchSettings(ctx, map[string]any{
	"search_settings": map[string]any{
		"searchable_content": map[string]any{
			"placeholder_text": "Search products",
			"product":          map[string]any{"enabled": true, "display_heading": "Product", "excluded": []any{map[string]any{"id": 4, "name": "Gift Card"}}},
			"product_categories": map[string]any{
				"enabled": true, "hide_parent_category": true, "display_heading": "Product Categories",
				"excluded": []any{map[string]any{"id": 16, "name": "Clearance"}},
			},
			"blog":        map[string]any{"enabled": true, "display_heading": "Blog Posts", "excluded": []any{map[string]any{"id": 13, "name": "Store News"}}},
			"other_pages": map[string]any{"enabled": true, "display_heading": "Other Pages", "excluded": []any{map[string]any{"id": 4, "name": "Home - Copy"}}},
		},
		"search_fields": map[string]any{
			"match_keywords_exactly": false,
			"match_full_sentences":   false,
			"fields": []any{
				map[string]any{"field": "title", "priority": 1},
				map[string]any{"field": "tags", "priority": 2},
				map[string]any{"field": "category", "priority": 3},
				map[string]any{"field": "description", "priority": 4},
				map[string]any{"field": "sku", "priority": 5},
				map[string]any{"field": "brand", "priority": 6},
			},
		},
		"synonyms": map[string]any{
			"groups": []any{
				map[string]any{"keywords": []any{"mobile", "phone", "telephone"}},
				map[string]any{"keywords": []any{"shoe", "footwear", "sneaker"}},
			},
		},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["search_settings"].(map[string]any)
fmt.Println(settings["searchable_content"].(map[string]any)["placeholder_text"], len(settings["search_fields"].(map[string]any)["fields"].([]any)))

